/**
 * Owner-authorized Phase 2 one-shot: frozen manifest → immutable repository insert.
 * Does NOT use TireDs4ShadowProcessorService or Producer (allowlist-safe).
 * Mirrors processor persist path: readForTrip + mapper + insertShadowInputImmutable.
 */
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { PrismaClient } = require('@prisma/client');

const ORG = 'faa710c9-6d91-4079-a7d5-91fdccdec14a';
const AUDI = 'c10351f8-b6a2-4258-947f-631aeaa6d359';
const ARTEON = '8c850ff1-4201-432b-af2e-2711dbc7ca48';
const TESLA_PREFIX = '68868291';
const TIGUAN_PREFIX = '19fedd4b';
const ADAPTER = 'tire-ds4-shadow-input-v1.1.1';
const BASELINE_SHA = '1b2cf483c3ddb93cdeddd7b5b58c420873319795';
const APPROVED_HASH = '44142957b8c409dd0fa34f4d2dede043e5a2018af1ce2871fed82f731babd798';
const MAX_AUDI = 30;
const MAX_ARTEON = 12;
const MAX_TOTAL = 42;

const execute = process.argv.includes('--execute');
const backendRoot =
  process.argv.find((a) => a.startsWith('--backend='))?.slice(10) ||
  '/opt/synqdrive/current/backend';
const manifestPath =
  process.argv.find((a) => a.startsWith('--manifest='))?.slice(11) ||
  '/tmp/tire-ds4-phase2-preflight.json';
const outPath =
  process.argv.find((a) => a.startsWith('--out='))?.slice(6) ||
  '/tmp/tire-ds4-phase2-controlled-once-report.json';

function loadDist(rel) {
  return require(path.join(backendRoot, 'dist/src', rel));
}

function manifestHash(rows) {
  const canonical = [...rows]
    .sort((a, b) => a.tireTripUsageLedgerId.localeCompare(b.tireTripUsageLedgerId))
    .map((r) => ({
      ledgerId: r.tireTripUsageLedgerId,
      tripId: r.tripId,
      vehicleId: r.vehicleId,
      runId: r.expectedRunId,
      adapter: ADAPTER,
    }));
  return crypto.createHash('sha256').update(JSON.stringify(canonical)).digest('hex');
}

async function redisQueueDepth() {
  const host = process.env.REDIS_HOST;
  const port = process.env.REDIS_PORT || '6379';
  const pw = process.env.REDIS_PASSWORD;
  const db = process.env.REDIS_DB || '0';
  if (!host) return { error: 'REDIS_HOST_missing', total: null };
  const { spawnSync } = require('child_process');
  const auth = pw ? ['-a', pw] : [];
  const base = ['redis-cli', '-h', host, '-p', port, '-n', db, ...auth];
  const rc = (cmd, ...args) =>
    spawnSync(base[0], base.slice(1).concat([cmd, ...args]), { encoding: 'utf8' }).stdout.trim();
  let total = 0;
  for (const suffix of ['wait', 'delayed', 'active', 'failed', 'prioritized']) {
    const key = `bull:dimo.tire.ds4-shadow:${suffix}`;
    const t = rc('TYPE', key);
    if (t === 'list') total += parseInt(rc('LLEN', key) || '0', 10);
    else if (t === 'zset') total += parseInt(rc('ZCARD', key) || '0', 10);
  }
  return { total };
}

function fail(code, msg) {
  const err = new Error(msg);
  err.code = code;
  throw err;
}

async function preflightEnv(prisma) {
  const enabled = (process.env.TIRE_DS4_SHADOW_ENABLED || '').toLowerCase();
  if (!['1', 'true', 'yes', 'on'].includes(enabled)) {
    fail('PREFLIGHT', 'TIRE_DS4_SHADOW_ENABLED not true');
  }
  const catchup = (process.env.TIRE_DS4_SHADOW_CATCHUP_ENABLED || 'false').toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(catchup)) {
    fail('PREFLIGHT', 'TIRE_DS4_SHADOW_CATCHUP_ENABLED must be false');
  }
  const allow = process.env.TIRE_DS4_SHADOW_VEHICLE_ALLOWLIST || '';
  if (!allow.includes(TESLA_PREFIX) || !allow.includes(TIGUAN_PREFIX)) {
    fail('PREFLIGHT', 'allowlist must include Tesla+Tiguan');
  }
  if (allow.includes('c10351f8') || allow.includes('8c850ff1')) {
    fail('PREFLIGHT', 'Audi/Arteon must not be on production allowlist');
  }
  const v3auth = (process.env.TIRE_WEAR_V3_CUSTOMER_READ_AUTHORITATIVE || '').toLowerCase();
  if (!['1', 'true', 'yes', 'on'].includes(v3auth)) {
    fail('PREFLIGHT', 'V3 authoritative must be on');
  }
  const priorShadow = (process.env.TIRE_WEAR_V3_PRIOR_SHADOW_WRITE_ENABLED || 'false').toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(priorShadow)) {
    fail('PREFLIGHT', 'prior shadow write must be off');
  }
}

async function validateManifestRow(prisma, repository, tripRead, frozen) {
  const ledgerId = frozen.tireTripUsageLedgerId;
  if (frozen.organizationId !== ORG) fail('MANIFEST', `org mismatch ${ledgerId}`);
  if (frozen.vehicleId !== AUDI && frozen.vehicleId !== ARTEON) {
    fail('MANIFEST', `vehicle not authorized ${ledgerId}`);
  }

  const ledger = await prisma.tireTripUsageLedger.findFirst({
    where: {
      id: ledgerId,
      organizationId: ORG,
      vehicleId: frozen.vehicleId,
      tripId: frozen.tripId,
      invalidatedAt: null,
    },
    select: {
      id: true,
      tireSetupId: true,
      distanceKm: true,
      tripStartedAt: true,
      tripEndedAt: true,
    },
  });
  if (!ledger) fail('INTEGRITY', `ledger invalid ${ledgerId}`);
  if (ledger.tireSetupId !== frozen.tireSetupId) {
    fail('INTEGRITY', `tireSetupId drift ${ledgerId}`);
  }

  if (await repository.hasTerminalMarker(ledgerId, ADAPTER)) {
    fail('INTEGRITY', `terminal marker ${ledgerId}`);
  }

  const run = await prisma.diV0MotionCoreShadowRunV1.findFirst({
    where: {
      id: frozen.expectedRunId,
      organizationId: ORG,
      vehicleId: frozen.vehicleId,
      tripId: frozen.tripId,
      shadowStatus: 'SUCCEEDED',
    },
    select: {
      id: true,
      combinedInputIdentity: true,
      pinnedSnapshotHash: true,
      contentFingerprint: true,
      shadowBundleVersion: true,
    },
  });
  if (!run) fail('INTEGRITY', `DS4 run not SUCCEEDED ${ledgerId}`);

  const latest = await prisma.diV0MotionCoreShadowRunV1.findFirst({
    where: {
      organizationId: ORG,
      vehicleId: frozen.vehicleId,
      tripId: frozen.tripId,
      shadowStatus: 'SUCCEEDED',
    },
    orderBy: { createdAt: 'desc' },
    select: { id: true },
  });
  if (latest?.id !== frozen.expectedRunId) {
    fail('INTEGRITY', `newer DS4 run replaced expected ${ledgerId}`);
  }

  if (run.combinedInputIdentity !== frozen.combinedInputIdentity) {
    fail('IDENTITY', `combinedInputIdentity drift ${ledgerId}`);
  }
  if (run.pinnedSnapshotHash !== frozen.pinnedSnapshotHash) {
    fail('IDENTITY', `pinnedSnapshotHash drift ${ledgerId}`);
  }
  if (run.contentFingerprint !== frozen.contentFingerprint) {
    fail('IDENTITY', `contentFingerprint drift ${ledgerId}`);
  }

  const existing = await prisma.tireDs4MotionShadowInputV1.findFirst({
    where: {
      tireTripUsageLedgerId: ledgerId,
      adapterVersion: ADAPTER,
      diV0MotionCoreShadowRunId: frozen.expectedRunId,
    },
  });
  if (existing) fail('INTEGRITY', `adapter row already exists ${ledgerId}`);

  const read = await tripRead.readForTrip(ORG, frozen.vehicleId, frozen.tripId);
  if (read.status !== 'SUCCEEDED' && read.status !== 'SUCCEEDED_EMPTY') {
    fail('READ', `readForTrip ${read.status} ${ledgerId}`);
  }
  if (read.runId !== frozen.expectedRunId) {
    fail('READ', `runId mismatch ${ledgerId}`);
  }
  if (read.combinedInputIdentity !== frozen.combinedInputIdentity) {
    fail('READ', `read identity mismatch ${ledgerId}`);
  }
  if (read.pinnedSnapshotHash !== frozen.pinnedSnapshotHash) {
    fail('READ', `read snapshot mismatch ${ledgerId}`);
  }

  return { ledger, run, read };
}

async function persistOne(repository, prisma, mapFns, frozen, ctx) {
  const { ledger, run, read } = ctx;
  const { mapDs4TripMapToTireShadowInput, eventQualityCoverageFromPayload } = mapFns;

  const inputPayload = mapDs4TripMapToTireShadowInput(read, {
    tripDistanceKm: ledger.distanceKm,
    tripStartedAt: ledger.tripStartedAt,
    tripEndedAt: ledger.tripEndedAt,
  });
  const eventQualityCoverage = eventQualityCoverageFromPayload(inputPayload);
  const eventsAlgorithmVersion = read.algorithmVersions?.events ?? 'unknown';
  const speedAuthority = read.speedAuthority ?? 'unknown';
  const shadowBundleVersion = read.algorithmVersions?.bundle ?? run.shadowBundleVersion;

  if (inputPayload.temporalCoverage !== frozen.temporalCoverage) {
    fail('STOP', `temporalCoverage drift ${frozen.tireTripUsageLedgerId}`);
  }
  if (eventQualityCoverage !== frozen.eventQualityCoverage) {
    fail('STOP', `eventQualityCoverage drift ${frozen.tireTripUsageLedgerId}`);
  }

  const result = await repository.insertShadowInputImmutable({
    organizationId: ORG,
    vehicleId: frozen.vehicleId,
    tripId: frozen.tripId,
    tireSetupId: ledger.tireSetupId,
    tireTripUsageLedgerId: ledger.id,
    diV0MotionCoreShadowRunId: read.runId,
    workItemId: read.workItemId,
    combinedInputIdentity: read.combinedInputIdentity,
    pinnedSnapshotHash: read.pinnedSnapshotHash,
    contentFingerprint: run.contentFingerprint,
    shadowBundleVersion,
    speedAuthority,
    eventsAlgorithmVersion,
    adapterVersion: ADAPTER,
    eventQualityCoverage,
    temporalCoverage: inputPayload.temporalCoverage,
    ds4ReadStatus: read.status,
    inputPayload,
  });

  if (result === 'evidence_immutable_conflict') {
    fail('STOP', `immutable conflict ${frozen.tireTripUsageLedgerId}`);
  }
  return result;
}

async function main() {
  const prisma = new PrismaClient();
  const { TireDs4ShadowRepository } = loadDist(
    'modules/vehicle-intelligence/tires/ds4-shadow/tire-ds4-shadow.repository',
  );
  const { DiV0MotionCoreShadowTripMapReadService } = loadDist(
    'modules/vehicle-intelligence/driving-intelligence/motion-core-shadow-worker/di-v0-motion-core-shadow-trip-map-read.service',
  );
  const mapFns = loadDist(
    'modules/vehicle-intelligence/tires/ds4-shadow/tire-ds4-shadow-input.mapper',
  );

  const repository = new TireDs4ShadowRepository(prisma);
  const tripRead = new DiV0MotionCoreShadowTripMapReadService(prisma);

  const report = {
    executionPath: 'MANIFEST_SCOPED_REPOSITORY_HARNESS',
    baselineSha: BASELINE_SHA,
    approvedManifestHash: APPROVED_HASH,
    phase: execute ? 'execute' : 'preflight',
  };

  try {
    await preflightEnv(prisma);

    const raw = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    const frozenRows = raw.candidates;
    if (!Array.isArray(frozenRows) || frozenRows.length !== MAX_TOTAL) {
      fail('MANIFEST', `expected ${MAX_TOTAL} candidates, got ${frozenRows?.length}`);
    }

    const audi = frozenRows.filter((r) => r.vehicleId === AUDI);
    const arteon = frozenRows.filter((r) => r.vehicleId === ARTEON);
    if (audi.length !== MAX_AUDI || arteon.length !== MAX_ARTEON) {
      fail('MANIFEST', `vehicle caps audi=${audi.length} arteon=${arteon.length}`);
    }

    const hash = manifestHash(frozenRows);
    report.computedManifestHash = hash;
    report.manifestHashVerified = hash === APPROVED_HASH;
    if (!report.manifestHashVerified) {
      fail('MANIFEST', `hash mismatch computed=${hash}`);
    }

    report.baselineCounts = {
      adapterV111: await prisma.tireDs4MotionShadowInputV1.count({
        where: { adapterVersion: ADAPTER },
      }),
      priorShadow: await prisma.tireWearV3PriorShadowV1.count(),
      ledgerValid: await prisma.tireTripUsageLedger.count({ where: { invalidatedAt: null } }),
      v2Snapshots: await prisma.tireHealthSnapshot.count(),
      ds4RunsOrg: await prisma.diV0MotionCoreShadowRunV1.count({ where: { organizationId: ORG } }),
    };

    report.queueDepthBefore = await redisQueueDepth();

    const validated = [];
    for (const row of [...frozenRows].sort((a, b) =>
      a.tireTripUsageLedgerId.localeCompare(b.tireTripUsageLedgerId),
    )) {
      validated.push({
        frozen: row,
        ctx: await validateManifestRow(prisma, repository, tripRead, row),
      });
    }

    report.preflightVerdict = 'PASS';
    report.audiAuthorized = audi.length;
    report.arteonAuthorized = arteon.length;
    report.totalAuthorized = frozenRows.length;

    if (!execute) {
      report.verdict = 'PREFLIGHT_PASS_READY';
      fs.writeFileSync(outPath, JSON.stringify(report, null, 2));
      console.log(JSON.stringify(report));
      return;
    }

    const results = [];
    let attempted = 0;
    let inserted = 0;
    let unchanged = 0;

    for (const { frozen, ctx } of validated) {
      attempted += 1;
      if (attempted > MAX_TOTAL) fail('CAP', 'attempts exceeded 42');

      await validateManifestRow(prisma, repository, tripRead, frozen);
      const depthBefore = (await redisQueueDepth()).total ?? 0;

      const result = await persistOne(repository, prisma, mapFns, frozen, ctx);

      const depthAfter = (await redisQueueDepth()).total ?? 0;
      if (depthAfter > depthBefore) {
        fail('STOP', `queue depth increased ledger=${frozen.tireTripUsageLedgerId}`);
      }

      if (result === 'inserted') inserted += 1;
      else if (result === 'unchanged') unchanged += 1;

      results.push({
        ledgerId: frozen.tireTripUsageLedgerId,
        vehicleId: frozen.vehicleId,
        tripId: frozen.tripId,
        result,
      });
    }

    const verification = [];
    for (const row of frozenRows) {
      const mat = await prisma.tireDs4MotionShadowInputV1.findFirst({
        where: {
          tireTripUsageLedgerId: row.tireTripUsageLedgerId,
          adapterVersion: ADAPTER,
          diV0MotionCoreShadowRunId: row.expectedRunId,
        },
      });
      verification.push({
        ledgerId: row.tireTripUsageLedgerId,
        present: mat != null,
        temporalCoverage: mat?.temporalCoverage ?? null,
        eventQualityCoverage: mat?.eventQualityCoverage ?? null,
        contentFingerprint: mat?.contentFingerprint ?? null,
        ds4ReadStatus: mat?.ds4ReadStatus ?? null,
      });
    }

    report.afterCounts = {
      adapterV111: await prisma.tireDs4MotionShadowInputV1.count({
        where: { adapterVersion: ADAPTER },
      }),
      priorShadow: await prisma.tireWearV3PriorShadowV1.count(),
      ledgerValid: await prisma.tireTripUsageLedger.count({ where: { invalidatedAt: null } }),
      v2Snapshots: await prisma.tireHealthSnapshot.count(),
      ds4RunsOrg: await prisma.diV0MotionCoreShadowRunV1.count({ where: { organizationId: ORG } }),
    };

    report.results = results;
    report.verification = verification;
    report.totalAttempted = attempted;
    report.inserted = inserted;
    report.unchanged = unchanged;
    report.skipped = 0;
    report.failed = 0;
    report.notProcessed = 0;
    report.audiInserted = results.filter(
      (r) => r.vehicleId === AUDI && r.result === 'inserted',
    ).length;
    report.arteonInserted = results.filter(
      (r) => r.vehicleId === ARTEON && r.result === 'inserted',
    ).length;
    report.deltaAdapterRows = report.afterCounts.adapterV111 - report.baselineCounts.adapterV111;
    report.queueDepthAfter = await redisQueueDepth();
    report.retriesEnqueued = 0;

    const allPresent = verification.every((v) => v.present);
    report.verdict =
      allPresent && inserted === MAX_TOTAL && report.deltaAdapterRows === MAX_TOTAL
        ? 'SUCCESS'
        : 'PARTIAL';

    fs.writeFileSync(outPath, JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report));
  } finally {
    await prisma.$disconnect();
  }
}

main().catch((e) => {
  console.error(JSON.stringify({ verdict: 'FAILED', code: e.code, error: String(e.message || e) }));
  process.exit(1);
});
